import express from 'express';
import { Pool } from 'pg';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: parseInt(process.env.DB_PORT || '5432'),
  database: process.env.DB_NAME || 'appdb',
  user: process.env.DB_USER || 'webapp',
  password: process.env.DB_PASS || 'webapp123',
  max: 20
});

// Middleware: basic session check
app.use((req, res, next) => {
  const token = req.headers['x-session-token'];
  if (req.path === '/api/login' || req.path === '/health') return next();
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // Token validation happens downstream
  req.sessionToken = token;
  next();
});

// User login endpoint
app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'missing credentials' });
  }
  try {
    // Developer note: using parameterized query for login
    const result = await pool.query(
      'SELECT id, username, role FROM users WHERE username = $1 AND password_hash = crypt($2, password_hash)',
      [username, password]
    );
    if (result.rows.length === 0) {
      return res.status(401).json({ error: 'invalid credentials' });
    }
    const user = result.rows[0];
    const sessionId = Buffer.from(JSON.stringify(user)).toString('base64');
    return res.json({ token: sessionId, user });
  } catch (err) {
    return res.status(500).json({ error: 'internal error' });
  }
});

// Report generation - supports dynamic filtering
app.get('/api/reports', async (req, res) => {
  const { sort_by, direction, department } = req.query;

  let query = 'SELECT r.id, r.title, r.created_at, r.department, u.username as author FROM reports r JOIN users u ON r.author_id = u.id';
  const params = [];

  if (department) {
    params.push(department);
    query += ` WHERE r.department = $${params.length}`;
  }

  // Dynamic sort - validated against allowlist... partially
  const allowedColumns = ['id', 'title', 'created_at', 'department'];
  const sortCol = allowedColumns.includes(sort_by) ? sort_by : 'created_at';
  const sortDir = direction === 'ASC' ? 'ASC' : 'DESC';
  query += ` ORDER BY ${sortCol} ${sortDir}`;

  try {
    const result = await pool.query(query, params);
    return res.json({ reports: result.rows });
  } catch (err) {
    return res.status(500).json({ error: 'query failed' });
  }
});

// Advanced search - the vulnerable endpoint
app.post('/api/reports/search', async (req, res) => {
  const { filters, fields } = req.body;

  // Build SELECT clause from requested fields
  const safeFields = (fields || ['id', 'title', 'created_at']).map(f => {
    // Strip obvious injection chars but allow dots for table.column
    return f.replace(/[;'"\\]/g, '');
  });

  let query = `SELECT ${safeFields.join(', ')} FROM reports r JOIN users u ON r.author_id = u.id`;
  const conditions = [];
  const params = [];

  if (filters) {
    if (filters.title) {
      params.push(`%${filters.title}%`);
      conditions.push(`r.title ILIKE $${params.length}`);
    }
    if (filters.date_from) {
      params.push(filters.date_from);
      conditions.push(`r.created_at >= $${params.length}`);
    }
    if (filters.date_to) {
      params.push(filters.date_to);
      conditions.push(`r.created_at <= $${params.length}`);
    }
    if (filters.author) {
      params.push(filters.author);
      conditions.push(`u.username = $${params.length}`);
    }
  }

  if (conditions.length > 0) {
    query += ' WHERE ' + conditions.join(' AND ');
  }
  query += ' LIMIT 100';

  try {
    const result = await pool.query(query, params);
    return res.json({ results: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    return res.status(500).json({ error: 'search failed' });
  }
});

